using UnityEditor;
public static class JojoPRefreshHost {
  public static string Run() {
    AssetDatabase.ImportAsset("Assets/AOT/Boot/BootPatchPipeline.cs", ImportAssetOptions.ForceUpdate);
    AssetDatabase.ImportAsset("Assets/AOT/Boot/LoadingView.cs", ImportAssetOptions.ForceUpdate);
    AssetDatabase.ImportAsset("Assets/Editor/Build/JojoPBuildWindow.cs", ImportAssetOptions.ForceUpdate);
    AssetDatabase.ImportAsset("Assets/Editor/Build/JojoPR2Uploader.cs", ImportAssetOptions.ForceUpdate);
    AssetDatabase.Refresh();
    return EditorApplication.isCompiling ? "compiling" : "idle";
  }
}
